import random, time, re
from itertools import chain
data=[random.randint(1,10**7) for _ in range(100000)]
def radix2(a):
    b=[[] for _ in range(4096)]; ap=[l.append for l in b]
    for x in a: ap[x&4095](x)
    b2=[[] for _ in range(4096)]; ap=[l.append for l in b2]
    for l in b:
        for x in l: ap[x>>12](x)
    return list(chain.from_iterable(b2))
def radix3(a):
    b2=[[] for _ in range(4096)]; ap=[l.append for l in b2]
    for x in a: ap[x&4095](x)
    b=[[] for _ in range(4096)]; ap=[l.append for l in b]
    for x in chain.from_iterable(b2): ap[x>>12](x)
    return list(chain.from_iterable(b))
def flagre(a):
    f=bytearray(10**7+1)
    for x in a: f[x]=1
    return [m.start() for m in re.finditer(b'\x01',f)]
for fn in (radix2,radix3,flagre):
